{"code":"def transform(grid):
    h=len(grid); w=len(grid[0])
    # Find occupied rows/columns and identify the separating empty line between two same-color objects.
    cells=[(r,c) for r in range(h) for c in range(w) if grid[r][c]!=0]
    out=[row[:] for row in grid]
    if not cells: return out
    # components by 4-connectivity
    seen=set(); comps=[]
    for p in cells:
        if p in seen: continue
        stack=[p]; seen.add(p); cc=[]
        while stack:
            r,c=stack.pop(); cc.append((r,c))
            for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if q in cells and q not in seen: seen.add(q); stack.append(q)
        comps.append(cc)
    if len(comps)<2: return out
    a,b=comps[0],comps[1]
    ar={r for r,c in a}; br={r for r,c in b}; ac={c for r,c in a}; bc={c for r,c in b}
    if max(ac)<min(bc) or max(bc)<min(ac):
        x=(max(ac)+min(bc))//2 if max(ac)<min(bc) else (max(bc)+min(ac))//2
        for r in range(h): out[r][x]=3
    elif max(ar)<min(br) or max(br)<min(ar):
        y=(max(ar)+min(br))//2 if max(ar)<min(br) else (max(br)+min(ar))//2
        for c in range(w): out[y][c]=3
    return out"}

