    out=[row[:] for row in grid]
    h=len(out); w=len(out[0]) if h else 0
    # Find two separated nonzero components/regions; in this task they lie side by side.
    cols=[]
    for c in range(w):
        if any(out[r][c]!=0 for r in range(h)):
            cols.append(c)
    if len(cols)>=2:
        # identify the empty column gap between the left and right occupied groups
        # split at the largest empty run between occupied columns
        runs=[]
        for a,b in zip(cols,cols[1:]):
            if b>a+1: runs.append((a+1,b-1))
        if runs:
            gap=max(runs,key=lambda x:x[1]-x[0])
            c=(gap[0]+gap[1])//2
            for r in range(h): out[r][c]=3
    return out"}

